'use strict';
function locationFilter(){return {floor:$('locFloor').value,zone:$('locZone').value,search:$('locSearch').value,status:$('locStatus').value}}
function updateLocationZones(){const floor=$('locFloor').value,previous=$('locZone').value,zones=E.LOCATION_LAYOUT.filter(x=>!floor||x.floor===Number(floor));$('locZone').innerHTML='<option value="">전체 보관존</option>'+zones.map(z=>`<option value="${z.zone}">${E.ZONE_NAMES[z.zone]} · ${z.code}</option>`).join('');if(zones.some(z=>z.zone===previous))$('locZone').value=previous}
function setupLocations(){for(const id of ['locZone','locStatus'])$(id).onchange=renderLocations;$('locSearch').oninput=renderLocations;$('locFloor').onchange=()=>{updateLocationZones();renderLocations();if($('locFloor').value)selectFloor(Number($('locFloor').value))};$('clearLocations').onclick=()=>{$('locFloor').value='2';$('locStatus').value='';$('locSearch').value='';updateLocationZones();$('locZone').value='';renderLocations()};for(const id of ['locationMap','locationsTable']){$(id).addEventListener('click',e=>{const target=e.target.closest('[data-location]');if(target)openDetail({type:'location',id:target.dataset.location})});$(id).addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('tr[data-location]'))openDetail({type:'location',id:e.target.dataset.location})})}$('exportLocations').onclick=exportLocations;updateLocationZones()}
function renderLocations(){const rows=E.locationRows(s,locationFilter()),sum=key=>rows.reduce((n,l)=>n+l[key],0);text('locCount',rows.length);text('locOccupied','재고 있음 '+rows.filter(l=>l.qty>0).length+' · 빈 위치 '+rows.filter(l=>l.qty===0).length);text('locQty',n(sum('qty')));text('locReserved',n(sum('reserved')));text('locAvailable',n(sum('qty')-sum('reserved')));text('locationResultCount',rows.length+'개 위치 · 모의 시각 '+time(s.time));
 const groups=E.LOCATION_LAYOUT.map(config=>{const filtered=rows.filter(l=>l.zone===config.zone);if(!filtered.length)return '';return `<section class="location-zone zone-${config.code}"><div class="location-zone-title"><span>${config.floor}F / ${config.code}</span><b>${E.ZONE_NAMES[config.zone]} 보관존</b><small>${filtered.length}개 위치 · ${n(filtered.reduce((n,l)=>n+l.qty,0))}개</small></div>${Array.from({length:config.aisles},(_,a)=>{const aisle=a+1,positions=filtered.filter(l=>l.aisle===aisle);if(!positions.length)return '';return `<div class="location-aisle"><span class="aisle-title">A${String(aisle).padStart(2,'0')} 통로</span><div class="location-shelves">${[2,1].map(level=>{const shelf=positions.filter(l=>l.level===level);if(!shelf.length)return '';return `<div class="location-shelf"><span>L${String(level).padStart(2,'0')}</span><div class="location-bays" style="--bays:${config.bays}">${shelf.map(l=>{const p=E.PRODUCTS.find(p=>p.id===l.sku);return `<button class="location-cell ${l.qty===0?'is-empty':l.reserved?'is-reserved':'is-occupied'}" style="grid-column:${l.bay}" data-location="${l.id}" aria-label="${l.id} 재고 상세" title="${l.id} · ${esc(p?.name||'미배정')} · 보유 ${l.qty} / 예약 ${l.reserved}"><span class="location-baycode">B${String(l.bay).padStart(2,'0')} <i>${l.reserved?'예약 '+l.reserved:l.qty?'보관':'비어 있음'}</i></span><b>${n(l.qty)}<small>개</small></b><span class="location-product">${esc(p?.name||'상품 미배정')}</span></button>`}).join('')}</div></div>`}).join('')}</div></div>`}).join('')}</section>`}).join('');html('locationMap',groups||'<p class="location-empty">조건에 맞는 로케이션이 없습니다. 검색어와 필터를 조정하세요.</p>');
 html('locationsTable',rows.map(l=>{const p=E.PRODUCTS.find(p=>p.id===l.sku);return `<tr data-location="${l.id}" tabindex="0" class="clickable"><td class="mono">${l.id}</td><td>${l.floor}F / ${E.ZONE_NAMES[l.zone]}</td><td class="stocktitle">${esc(p?.name||'미배정')}<small>${l.sku||'—'}</small></td><td class="num">${n(l.qty)}</td><td class="num">${n(l.reserved)}</td><td class="num">${n(l.qty-l.reserved)}</td><td class="num">${n(l.received)}</td><td class="num">${n(l.picked)}</td></tr>`}).join('')||'<tr><td colspan="8" class="emptymsg">조회 결과가 없습니다.</td></tr>')}
function locationDetail(id){const l=s.locations.find(l=>l.id===id),p=E.PRODUCTS.find(p=>p.id===l.sku),orders=s.orders.flatMap(o=>o.lines.filter(line=>line.reserved).flatMap(line=>(line.allocations||[]).filter(a=>a.locationId===id).map(a=>({order:o.id,qty:a.qty,state:E.ORDER_NAMES[o.state]})))),receipts=s.receipts.flatMap(r=>r.items.filter(i=>i.locationId===id&&r.state!=='DONE').map(i=>({id:r.id,qty:i.qty})));return `<h2 class="location-dialog-code">${id}</h2><p class="dialogdesc">${l.floor}층 / ${E.ZONE_NAMES[l.zone]} · A${String(l.aisle).padStart(2,'0')} 통로 · B${String(l.bay).padStart(2,'0')} 베이 · L${String(l.level).padStart(2,'0')}단</p><div class="helpline"><b>${esc(p?.name||'상품 미배정')}</b><br>${l.sku||'빈 위치 · 미배정'}</div><div class="detail-grid">${detailItem('보유 수량',n(l.qty)+'개')}${detailItem('피킹 예약',n(l.reserved)+'개')}${detailItem('추가 주문 가용',n(l.qty-l.reserved)+'개')}${detailItem('초기 배치',n(l.initial)+'개')}${detailItem('입하 누계',n(l.received)+'개')}${detailItem('피킹 누계',n(l.picked)+'개')}</div><h3>예약된 주문</h3>${orders.length?'<table><thead><tr><th>주문번호</th><th>현재 상태</th><th>예약</th></tr></thead><tbody>'+orders.map(o=>`<tr><td>${o.order}</td><td>${o.state}</td><td>${o.qty}개</td></tr>`).join('')+'</tbody></table>':'<p class="helpline">예약된 주문이 없습니다.</p>'}${receipts.length?'<h3>적치 예정</h3><p class="helpline">'+receipts.map(r=>r.id+' · '+r.qty+'개').join('<br>')+'</p>':''}<p class="helpline">보유 = 초기 배치 + 입하 누계 − 피킹 누계. 적치 예정 수량은 적치 완료 전까지 보유·가용에 포함하지 않습니다.</p>`}
function exportLocations(){const rows=E.locationRows(s,locationFilter()),out=[['모의시각','로케이션','층','보관존','상품ID','상품명','초기재고','보유수량','피킹예약','가용수량','입하누계','피킹누계','단위'],...rows.map(l=>[time(s.time),l.id,l.floor,E.ZONE_NAMES[l.zone],l.sku||'',E.PRODUCTS.find(p=>p.id===l.sku)?.name||'',l.initial,l.qty,l.reserved,l.qty-l.reserved,l.received,l.picked,'개'])],csv='\uFEFF'+out.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download='가상물류센터_로케이션재고.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(rows.length+'개 로케이션을 CSV로 저장했습니다.')}
